// node mods/sotn-ultimate/tools/builder/node/survey_psp_arrays.ts SRC_DIR MAP BIN BASE SOURCES_DIR
// Survey: the generated arrays of SRC_DIR (gen/** and "Generated by" files)
// located in BIN, and which are found as they are in a file of SOURCES_DIR
// (e.g. the US UMD's PSPBIN): those the builder could copy from the disc.
import * as fs from "node:fs";
import * as path from "node:path";
import { arrayBytes, parseCArrays, symbolAddresses } from "./c_arrays.ts";
import { ROOT } from "./util.ts";

const [srcDir, mapFile, binFile, baseHex, srcFiles] = process.argv.slice(2);
const base = parseInt(baseHex, 16);
const bin = new Uint8Array(fs.readFileSync(path.join(ROOT, binFile)));
const syms = symbolAddresses(path.join(ROOT, mapFile), ROOT);
const sources = fs.readdirSync(srcFiles).map((n) => [n, fs.readFileSync(path.join(srcFiles, n))] as const);
const files: string[] = [];
const walk = (d: string): void => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        const p = path.join(d, e.name);
        if (e.isDirectory()) {
            walk(p);
        } else if (/\.(c|h)$/.test(e.name) &&
                   (p.includes("/gen/") || /Generated by/.test(fs.readFileSync(p, "utf8").slice(0, 200)))) {
            files.push(p);
        }
    }
};
walk(path.join(ROOT, srcDir));
let located = 0;
let locBytes = 0;
let verb = 0;
let verbBytes = 0;
const notVerb: string[] = [];
const seen = new Set<string>();
for (const f of files) {
    for (const a of parseCArrays(f, [path.dirname(f), path.join(ROOT, "include"), path.join(ROOT, srcDir)])) {
        if (seen.has(a.name)) {
            continue;
        }
        seen.add(a.name);
        const b = arrayBytes(a);
        const at = (syms.get(a.name) ?? []).map((x) => x - base).find((o) =>
            o >= 0 && o + b.length <= bin.length && b.every((v, i) => bin[o + i] === v));
        if (at === undefined) {
            continue;
        }
        located++;
        locBytes += b.length;
        const hit = sources.find(([, s]) => s.indexOf(b) >= 0);
        if (hit) {
            verb++;
            verbBytes += b.length;
        } else {
            notVerb.push(a.name + " " + b.length);
        }
    }
}
console.log("%d arrays located (%d bytes); verbatim in %s: %d arrays (%d bytes); not: %d (%d bytes)",
            located, locBytes, srcFiles, verb, verbBytes, notVerb.length, locBytes - verbBytes);
console.log("  " + notVerb.slice(0, 15).join(", "));
